// Run with: node --test .github/scripts/owner-decisions.test.cjs
const test = require('node:test');
const assert = require('node:assert/strict');
const { parse, evaluate, summary } = require('./owner-decisions.cjs');

const comment = (d1, d2) => `## Owner decisions

<!-- Tick one option per decision. -->

**D1. What does \`#\` match?**
- [${d1[0]}] A: run ID prefix only (recommended) \`→ ready\`
- [${d1[1]}] B: run ID prefix or graph name \`→ ADR\`

**D2. Fallback name**
- [${d2[0]}] A: "Local user" \`→ ready\`
- [${d2[1]}] B: other \`→ ready\`

**When decided:** with A the issue becomes claude-ready.

---
_Generated by [Claude Code](https://claude.ai/code)_`;

test('text without the section has no decisions', () => {
  assert.equal(parse('just an issue'), null);
  assert.equal(evaluate(parse('just an issue')), null);
});

test('options are parsed with key, tick and outcome', () => {
  assert.deepEqual(parse(comment('x ', ' x'))[0], {
    id: 'D1',
    options: [
      { key: 'A', checked: true, outcome: 'ready' },
      { key: 'B', checked: false, outcome: 'adr' },
    ],
  });
});

test('an unticked decision is incomplete', () => {
  assert.deepEqual(evaluate(parse(comment('x ', '  '))), { complete: false });
});

test('two ticked options in one decision are incomplete', () => {
  assert.deepEqual(evaluate(parse(comment('xx', 'x '))), { complete: false });
});

test('all ticked options leading to ready make the issue ready', () => {
  const result = evaluate(parse(comment('x ', ' X')));
  assert.equal(result.complete, true);
  assert.equal(result.ready, true);
  assert.equal(summary(result.chosen), 'D1=A:ready;D2=B:ready');
});

test('one option leading to an ADR keeps the issue not ready', () => {
  const result = evaluate(parse(comment(' x', 'x ')));
  assert.equal(result.ready, false);
  assert.deepEqual(result.chosen[0], { id: 'D1', key: 'B', outcome: 'adr' });
});

test('an option without a known marker is never ready', () => {
  const text = '## Owner decisions\n\n**D1. Q?**\n- [x] A: something\n- [ ] B: other `→ maybe`\n';
  assert.deepEqual(evaluate(parse(text)).chosen, [{ id: 'D1', key: 'A', outcome: 'unknown' }]);
});

test('checkboxes outside the section or before the first decision are ignored', () => {
  const text = '## Scope\n- [x] item `→ ready`\n\n## Owner decisions\n- [x] stray `→ ready`\n\n**D1. Q?**\n- [ ] A `→ ready`\n\n## Notes\n- [x] later `→ ready`\n';
  assert.deepEqual(parse(text), [{ id: 'D1', options: [{ key: '1', checked: false, outcome: 'ready' }] }]);
});

test('a decision without options is incomplete', () => {
  assert.deepEqual(evaluate(parse('## Owner decisions\n\n**D1. Q?**\n')), { complete: false });
});

test('an issue form field renders the section as a level-3 heading', () => {
  const body = '### Feature ID\n\nF2.5b\n\n### Owner decisions\n\n**D1. Q?**\n- [x] A: x `→ ready`\n\n### Autonomy\n\nNeeds me\n- [x] not an option `→ adr`\n';
  assert.deepEqual(evaluate(parse(body)).chosen, [{ id: 'D1', key: 'A', outcome: 'ready' }]);
});
